class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self._limit_bytes = int(monthly_limit_mib * 1024 * 1024)
        # Per-month tracking:
        #   _counted: set of file names that have already counted towards quota this month
        #   _used: total bytes counted towards quota this month
        self._counted = {}
        self._used = {}

    def _ensure_month(self, month: str) -> None:
        if month not in self._counted:
            self._counted[month] = set()
            self._used[month] = 0

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        """month is a string like "2026-01"."""
        if size_bytes == 0:
            raise ValueError("Cannot upload a file of size 0.")
        if size_bytes < 0:
            raise ValueError("File size must be non-negative.")

        self._ensure_month(month)

        # Requirement 2: re-uploading the same name in the same month
        # does not count towards the limit a second time.
        if name in self._counted[month]:
            return

        new_used = self._used[month] + size_bytes
        if new_used > self._limit_bytes:
            raise ValueError(
                f"Upload would exceed monthly quota of "
                f"{self._limit_bytes} bytes for {month}."
            )

        self._used[month] = new_used
        self._counted[month].add(name)

    def delete(self, name: str, month: str) -> None:
        self._ensure_month(month)
        # Requirement 1: deleting a file does not give back quota.
        # We keep the name in _counted so that re-uploading the same name
        # in the same month also does not count again, and we do not
        # subtract from _used.
        # If the file was never uploaded (or not counted), this is a no-op.
        # We intentionally do NOT remove the name from _counted.

    def used_bytes(self, month: str) -> int:
        """How many bytes count towards the quota in the given month."""
        return self._used.get(month, 0)
